{
  "passages": [
    {
      "id": "m32",
      "about_topic": true,
      "says": "rule: keep to the right and use left lanes for passing when driving along a freeway"
    },
    {
      "id": "m33",
      "about_topic": true,
      "says": "rule: use the far left lane of a multi-lane freeway to pass traffic slower than the speed limit; rule: do not stay in the far left lane; rule: drive in the right lane when possible"
    },
    {
      "id": "m91",
      "about_topic": true,
      "says": "rule (law): large trucks cannot travel in the far left lane on many freeways with 3 or more lanes in each direction; rule (law): they must use the lane to the right of the far left lane for passing"
    },
    {
      "id": "m34",
      "about_topic": true,
      "says": "rule: drive in the right lane and leave the other lanes clear for passing when driving along a freeway"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"should\")",
      "text": "a driver SHOULD keep to the right AND use the left lanes for passing WHEN driving along a freeway",
      "sources": [
        {
          "id": "m32",
          "quote": "Traffic should keep to the right, using the left lanes for passing."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The passage's subject 'traffic' is written as 'a driver'."
    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Use\")",
      "text": "a driver SHOULD use the far left lane to pass traffic moving slower than the speed limit WHEN driving along a multi-lane freeway",
      "sources": [
        {
          "id": "m33",
          "quote": "Use the far left lane of a multi-lane freeway to pass traffic moving slower than the speed limit, but don't stay there."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"don't stay\")",
      "text": "a driver SHOULD NOT stay in the far left lane WHEN driving along a multi-lane freeway",
      "sources": [
        {
          "id": "m33",
          "quote": "Use the far left lane of a multi-lane freeway to pass traffic moving slower than the speed limit, but don't stay there."
        }
      ],
      "flags": [],
      "links": [],
      "note": "'there' is made explicit as the far left lane."
    },
    {
      "id": "s4",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Drive\")",
      "text": "a driver SHOULD drive in the right lane WHEN driving along a multi-lane freeway AND driving in the right lane is [?possible]",
      "sources": [
        {
          "id": "m33",
          "quote": "Drive in the right-hand lane when possible."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "possible",
          "note": "No measure is given for when driving in the right lane is possible."
        },
        {
          "code": "V",
          "span": "right lane",
          "note": "The passage says 'right-hand lane'; 'right lane' is used consistently."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s5",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"cannot\", \"must\")",
      "text": "EXCEPTION TO s2: a driver of a large truck MUST NOT travel in the far left lane AND MUST use the lane to the right of the far left lane for passing WHEN the freeway is one of [?many] freeways with 3 or more lanes in each direction",
      "sources": [
        {
          "id": "m91",
          "quote": "On many freeways with three or more lanes in each direction, large trucks cannot travel in the far left lane and must use the lane to the right for passing."
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "many",
          "note": "The handbook applies this to many, not necessarily all, freeways with 3 or more lanes in each direction."
        }
      ],
      "links": [
        "s2"
      ],
      "note": "The passage regulates large trucks, so the role is the driver of a large truck. It is written as an exception to the general far-left passing advice in s2."
    },
    {
      "id": "s6",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Get into the habit\")",
      "text": "a driver SHOULD drive in the right lane AND leave the other lanes clear for passing WHEN driving along a freeway",
      "sources": [
        {
          "id": "m34",
          "quote": "Get into the habit of driving in the right lane, leaving the other lanes clear for passing."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The advice to get into a habit is expressed as SHOULD."
    }
  ]
}
